import type { CommsPolicy, PreferenceCategory } from '@abc/rules';
import { placeholders } from './render';

/**
 * The template library (docs/16 §3): one short, plain message per thing a person
 * should hear about, described the same way on every channel (docs/01 §6.6).
 * `text` is used for WhatsApp, SMS, app notifications and the in-app feed, so it
 * must fit one SMS (160 GSM characters) with realistic values. Email gets a subject
 * and a slightly longer body. These rows are seeded as `approved` (db/seed.sql and
 * migration 0002, generated by `pnpm --filter @abc/comms templates:sql`).
 *
 * Changing approved copy means adding a new version, never editing one: the
 * database refuses edits to approved templates, because messages already sent
 * point at them.
 */

export const CHANNELS = ['whatsapp', 'push', 'sms', 'email', 'in_app'] as const;
export type Channel = (typeof CHANNELS)[number];

export type TemplateCategory = 'transactional' | 'alert' | 'marketing';

export const DEFAULT_LOCALE = 'en-ZW';

export interface TemplateDefinition {
  key: string;
  version: number;
  category: TemplateCategory;
  /** Preference category people can switch per channel. null: cannot be switched off (sign-in codes, chat replies). */
  preference: PreferenceCategory | null;
  /** Channel order from rule comms.fallback. null: fixed channels (a chat reply stays in the chat). */
  policy: CommsPolicy | null;
  channels: readonly Channel[];
  text: string;
  subject: string;
  email: string;
  /** Realistic values, used in tests (SMS length) and the docs. */
  example: Record<string, string>;
}

