const BY_KEY = new Map(TEMPLATE_LIBRARY.map((t) => [t.key, t]));

export function templateDefinition(key: string): TemplateDefinition {
  const t = BY_KEY.get(key);
  if (!t) throw new Error(`Unknown template ${key}`);
  return t;
}

/** WhatsApp template name as submitted to Meta. Chat replies are session messages, not templates. */
export function providerTemplateName(t: TemplateDefinition): string | null {
  return t.policy === null && t.preference === null ? null : `abc_${t.key}_v${t.version}`;
}

export interface TemplateRow {
  key: string;
  version: number;
  channel: Channel;
  locale: string;
  category: TemplateCategory;
  subject: string | null;
  body: string;
  providerTemplateName: string | null;
}

/** The comms.template rows for the library, one per template and channel. */
export function templateRows(library: readonly TemplateDefinition[] = TEMPLATE_LIBRARY): TemplateRow[] {
  const rows: TemplateRow[] = [];
  for (const t of library) {
    for (const channel of t.channels) {
      rows.push({
        key: t.key,
        version: t.version,
        channel,
        locale: DEFAULT_LOCALE,
        category: t.category,
        subject: channel === 'email' || channel === 'push' || channel === 'in_app' ? t.subject : null,
        body: channel === 'email' ? `${t.email}${EMAIL_FOOTER}` : t.text,
        providerTemplateName: channel === 'whatsapp' ? providerTemplateName(t) : null,
      });
    }
  }
  return rows;
}

function sqlString(s: string | null): string {
  if (s === null) return 'NULL';
  return s.includes('\n') ? `E'${s.replace(/\\/g, '\\\\').replace(/'/g, "\\'").replace(/\n/g, '\\n')}'` : `'${s.replace(/'/g, "''")}'`;
}

export const TEMPLATE_SQL_BEGIN = '-- BEGIN comms template library (generated: pnpm --filter @abc/comms templates:sql)';
export const TEMPLATE_SQL_END = '-- END comms template library';

/** INSERT statements for the library, as pasted into db/seed.sql and migration 0002. */
export function templatesSql(rows: readonly TemplateRow[] = templateRows()): string {
  const values = rows.map(
    (r) =>
      `  (${sqlString(r.key)}, ${r.version}, ${sqlString(r.channel)}, ${sqlString(r.locale)}, ${sqlString(r.category)}, ${sqlString(r.subject)}, ${sqlString(r.body)}, ${sqlString(r.providerTemplateName)}, 'approved')`,
  );
  return [
    TEMPLATE_SQL_BEGIN,
    'INSERT INTO comms.template (key, version, channel, locale, category, subject, body, provider_template_name, status) VALUES',
    values.join(',\n'),
    'ON CONFLICT (key, version, channel, locale) DO NOTHING;',
    TEMPLATE_SQL_END,
  ].join('\n');
}

/** Parameters a template needs, across all its channels. */
export function templateParams(t: TemplateDefinition): string[] {
  return [...new Set([...placeholders(t.text), ...placeholders(t.subject), ...placeholders(t.email)])];
}
